    18→interface DiffViewDialogProps {
    19→  open: boolean;
    20→  worktreeDiff: WorktreeDiff | null;
    21→  taskId: string;
    22→  onOpenChange: (open: boolean) => void;
    23→  onRefreshDiff: () => Promise<void>;
    24→}
    25→
    26→/**
    27→ * Dialog displaying the list of changed files with their status and line changes
    28→ */
    29→export function DiffViewDialog({
    30→  open,
    31→  worktreeDiff,
    32→  taskId,
    33→  onOpenChange,
    34→  onRefreshDiff
    35→}: DiffViewDialogProps) {
    36→  // State for tracking which file is being considered for discard
    37→  const [fileToDiscard, setFileToDiscard] = useState<string | null>(null);
    38→  // State for showing success feedback after file discard
    39→  const [discardSuccess, setDiscardSuccess] = useState<string | null>(null);
    40→  // State for tracking discard operation in progress (prevents race conditions)
    41→  const [isDiscarding, setIsDiscarding] = useState(false);
    42→  // State for showing error message after failed discard operation
    43→  const [discardError, setDiscardError] = useState<{ file: string; message: string } | null>(null);
    44→
    45→  /**
    46→   * Handles discarding changes to a single file via git restore.
    47→   * Calls IPC, shows success feedback, and refreshes the diff view.
    48→   */
    49→  const handleDiscardFile = useCallback(async () => {
    50→    if (!fileToDiscard || isDiscarding) return;
    51→
    52→    const filePath = fileToDiscard;
    53→    // Clear the confirmation dialog immediately
    54→    setFileToDiscard(null);
    55→    // Clear any previous error
    56→    setDiscardError(null);
    57→    // Set loading state to prevent race conditions
    58→    setIsDiscarding(true);
    59→
    60→    try {
    61→      const result = await window.electronAPI.discardWorktreeFile(taskId, filePath);
    62→
    63→      if (result.success && result.data?.success) {
    64→        // Show success feedback
    65→        setDiscardSuccess(filePath);
    66→        // Clear success message after 3 seconds
    67→        setTimeout(() => setDiscardSuccess(null), 3000);
    68→        // Refresh the diff view to show updated file list
    69→        await onRefreshDiff();
    70→      } else {
    71→        // IPC call succeeded but git restore failed - show error
    72→        const errorMessage = result.error || result.data?.error || 'Failed to discard file changes';
    73→        setDiscardError({ file: filePath, message: errorMessage });
    74→      }
    75→    } catch (error) {
    76→      // Unexpected error (IPC failure, network error, etc.)
    77→      const errorMessage = error instanceof Error ? error.message : 'An unexpected error occurred';
    78→      setDiscardError({ file: filePath, message: errorMessage });
    79→    } finally {
    80→      // Always clear loading state
    81→      setIsDiscarding(false);
    82→    }
    83→  }, [fileToDiscard, isDiscarding, taskId, onRefreshDiff]);
    84→
    85→  return (
    86→    <>
    87→      <AlertDialog open={open} onOpenChange={onOpenChange}>
