    99→          {discardSuccess && (
   100→            <div className="flex items-center gap-2 px-3 py-2 rounded-lg bg-success/10 text-success text-sm">
   101→              <CheckCircle2 className="h-4 w-4 shrink-0" />
   102→              <span>
   103→                Discarded changes to <span className="font-mono">{discardSuccess}</span>
   104→              </span>
   105→            </div>
   106→          )}
   107→          <div className="flex-1 overflow-auto min-h-0 -mx-6 px-6">
   108→            {worktreeDiff?.files && worktreeDiff.files.length > 0 ? (
   109→              <div className="space-y-2">
   110→                {worktreeDiff.files.map((file, idx) => (
   111→                  <div
   112→                    key={idx}
   113→                    className="flex items-center justify-between p-2 rounded-lg bg-secondary/30 hover:bg-secondary/50 transition-colors"
   114→                  >
   115→                    <div className="flex items-center gap-2 min-w-0 flex-1">
   116→                      <FileCode className={cn(
   117→                        'h-4 w-4 shrink-0',
   118→                        file.status === 'added' && 'text-success',
   119→                        file.status === 'deleted' && 'text-destructive',
   120→                        file.status === 'modified' && 'text-info',
   121→                        file.status === 'renamed' && 'text-warning'
   122→                      )} />
   123→                      <span className="text-sm font-mono truncate">{file.path}</span>
   124→                    </div>
